node = nuke.thisNode() 
node['licenseCheckTrigger'].execute() 
proceed = bool(node['licenseCheckResult'].getValue()) 
if proceed: 
  knobsString = node.writeKnobs(nuke.WRITE_NON_DEFAULT_ONLY) 
  hasTracks = 'autoTracksKnob' in knobsString 
  if hasTracks: 
    proceed = nuke.ask('Proceeding will reset the existing automatic feature tracks. Are you sure?') 
if proceed: 
  node['executeType'].setValue(0) 
  first = max(node.firstFrame(), int(node['startFrame'].getValue())) 
  last = min(node.lastFrame(), int(node['endFrame'].getValue())) 
  rangeFwd = nuke.FrameRange(first, last, 1) 
  rangeBwd = nuke.FrameRange(last, first, -1) 
  if node['trackFwdAndBwd'].getValue() != 0.0: 
    ranges = nuke.FrameRanges([rangeFwd, rangeBwd]) 
  else: 
    ranges = nuke.FrameRanges([rangeFwd]) 
  try: 
    nuke.execute( node, ranges ) 
  except RuntimeError as err: 
    raise err

